test('addLine returns distinct objects', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result1 = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  const result2 = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });

  assert.notEqual(result1.value, result2.value);
  assert.notEqual(result1.value.lines, result2.value.lines);
  assert.deepEqual(result1.value, result2.value);
});

