test('invoiceTotals returns subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // C-001 is gold tier (5% discount): 95000 × 5 / 100 = 4750
  // Taxable: 95000 - 4750 = 90250
  // VAT (21%): 90250 × 21 / 100 = 18952.5 → 18952 (banker's rounding)
  // Total: 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

test('invoiceTotals sums multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // Subtotal: 137500
  // C-001 is gold tier (5% discount): 6875
  // DEV-HOUR taxable: 90250, VAT (21%): 18952
  // DES-HOUR taxable: 40375, VAT (21%): 8478.75 → 8479 (banker's rounding)
  // Total VAT: 27431, Total: 137500 - 6875 + 27431 = 158056
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 6875);
  assert.equal(totals.vat, 27431);
  assert.equal(totals.total, 158056);
});

test('invoiceTotals sums complex line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // Subtotal: 105960, Discount (5%): 5298
  // DEV-HOUR: 76000, taxable 72200, VAT 21%: 15162
  // DES-HOUR: 25500, taxable 24225, VAT 21%: 5087.25 → 5087
  // ICON-SET: 1960, taxable 1862, VAT 21%: 391.02 → 391
  // STICKER: 2500, taxable 2375, VAT 21%: 498.75 → 499
  // Total VAT: 21139, Total: 105960 - 5298 + 21139 = 121801
  assert.equal(totals.subtotal, 105960);
  assert.equal(totals.discount, 5298);
  assert.equal(totals.vat, 21139);
  assert.equal(totals.total, 121801);
});

