  assert.equal(normalizeId(' c-001 '), 'C-001');
  assert.equal(normalizeId(' C-002 '), 'C-002');
  assert.equal(normalizeId('  c-003  '), 'C-003');
});

test('normalizeId is idempotent', () => {
  const id = normalizeId('c-001');
  assert.equal(normalizeId(id), id);
});

test('createInvoice accepts lowercase customer ID', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice accepts mixed case customer ID with spaces', () => {
  const result = createInvoice({
    customerId: ' c-002 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-002');
});

test('createInvoice stores normalized customer ID', () => {
  const result = createInvoice({
    customerId: ' C-003 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice with various customer ID formats', () => {
  const formats = ['c-001', 'C-001', ' c-001', 'c-001 ', ' c-001 ', 'C-001', ' C-001 '];

  for (const id of formats) {
    const result = createInvoice({
      customerId: id,
      issueDate: '2025-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    });
    assert.equal(result.ok, true, `Failed for ID: "${id}"`);
    assert.equal(result.value.customerId, 'C-001', `Wrong normalized ID for: "${id}"`);
  }
});

